    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>يلتزم جميع العاملين بارتداء الواقيات الشخصية المناسبة لحماية كل من مقدم الخدمة والمريض من انتقال العدوى.</p><h3>أنواع الواقيات الشخصية ودواعي استخدامها:</h3><ul><li><strong>1. غطاء الرأس:</strong> في العمليات الجراحية، الجروح الكبيرة، تركيب القسطرة المركزية، خلط المحاليل، وتغليف الآلات.</li><li><strong>2. واقي الوجه والنظارة الواقية:</strong> عند احتمالية تناثر الرذاذ أو الدم (علاج الأسنان، تشفيط الجهاز التنفسي، غسيل الآلات).</li><li><strong>3. الأقنعة التنفسية:</strong> قناع جراحي (للعمليات، الرذاذ، نقص المناعة) وقناع عالي الكفاءة <strong>N95 / FFP2</strong> (لمرضى السل، الحصبة، الجديري المائي، والأمراض المستجدة).</li><li><strong>4. المرايل البلاستيكية والعباءات (الجاونات):</strong> معقمة (للعمليات والقساطر المركزية) وغير معقمة (عند احتمال تناثر السوائل).</li><li><strong>5. القفازات (3 أنواع):</strong> معقمة (للعمليات، القساطر المركزية والبولية)، نظيفة لاتكس (للكانيولا، سحب العينات، الغيارات الملوثة)، سميكة شديدة التحمل (للمخلفات، غسيل الآلات، تنظيف البيئة).</li><li><strong>6. واقيات الأقدام (البوت/حذاء العمليات):</strong> لغرف العمليات، تنظيف البيئة والآلات، ونقل النفايات (يمنع استخدام الأكياس البلاستيكية للأحذية).</li></ul><h3>ترتيب ارتداء وخلع الواقيات (في العزل):</h3><p><strong>الارتداء:</strong> 1. العباءة ⬅ 2. الماسك ⬅ 3. واقي العين ⬅ 4. القفازات.<br><strong>الخلع:</strong> 1. القفازات ⬅ 2. نظافة الأيدي ⬅ 3. العباءة ⬅ 4. واقي العين ⬅ 5. الماسك ⬅ 6. نظافة الأيدي.</p></div>",
    "plain_text": "الواقيات الشخصية PPE غطاء الرأس واقي الوجه والنظارة الواقية القناع الجراحي الماسك N95 المرايل البلاستيكية العباءات الجاونات القفازات المعقمة والنظيفة وشديدة التحمل واقيات الأقدام ترتيب ارتداء وخلع الواقيات الشخصية.",
