    "purpose": "أساليب العمل المانعة للتلوث الأسلوب النظيف الأسلوب المانع للتلوث الأسلوب المعقم تركيب قسطرة الوريد المركزي CVC الحزمة الوقائية للقسطرة المركزية القسطرة البولية ...",
    "responsibilities": "الأطباء بجميع الفئات - مشرفة القسم - التمريض",
    "content_html": "<div class='policy-doc'><h3>أنواع أساليب العمل الطبي:</h3><ul><li><strong>1. الأسلوب النظيف:</strong> للتعامل مع جلد سليم (كشف ظاهري) - غسل أيدي بسيط وقفاز عند الحاجة.</li><li><strong>2. الأسلوب المانع للتلوث:</strong> للإجراءات الاختراقية البسيطة خارج العمليات - دلك كحولي وقفاز معقم ومطهر جلد.</li><li><strong>3. الأسلوب المعقم (الجراحي):</strong> للتعامل مع الأماكن المعقمة بالجسم - غسل جراحي، واقيات كاملة معقمة، وآلات معقمة.</li></ul><h3>الحزمة الوقائية لقسطرة الوريد المركزي (CVC Bundle):</h3><ul><li><strong>أثناء التركيب:</strong> 1. استخدام عبوة مسبقة الإعداد (Insertion Kit) 2. غسل أيدي جراحي 3. أقصى واقيات شخصية جراحية وفرش معقم كامل 4. تطهير الجلد بالكلورهيكسيدين 2% كحولي 5. تفضيل الوريد تحت الترقوة (Subclavian Vein).</li><li><strong>أثناء العناية:</strong> تقييم الحاجة يومياً، دلك اليدين بالكحول، تغيير غيار الشاش كل يومين واللاصق الشفاف كل 7 أيام، تطهير المدخل بالكحول 70% قبل كل استخدام، تغيير جهاز الوريد كل 7 أيام (وفوراً بعد الدم أو خلال 24 ساعة للدهون).</li></ul><h3>الحزمة الوقائية للقسطرة البولية (CAUTI Bundle):</h3><ul><li><strong>أثناء التركيب:</strong> تجنب التركيب إلا لضرورة، استخدام Insertion Kit، تطهير الأيدي، قفازات معقمة، تنظيف وتطهير العانة، فرش معقم، جيل معقم أحادي الاستخدام.</li><li><strong>أثناء العناية:</strong> نظافة يومية لمكان الإدخال، الحفاظ على نظام جمع البول مغلقاً، تدفق البول دون عائق، تثبيت الكيس تحت مستوى المريض وعدم ملامسته للأرض، وعاء تفريغ مخصص لكل مريض، والتقييم اليومي لرفعها.</li></ul></div>",
