    "dept": "العمليات - جميع الأقسام الجراحية",
    "purpose": "السياسة الخاصة بالعمليات الجراحية تهوية موجبة الضغط التخدير داخل غرفة العمليات الحفاظ على المجال المعقم منع الفورمالين لتعقيم الآلات تنظيف غرفة العمليات كلور 50...",
    "responsibilities": "مدير قسم العمليات - استشاري التخدير - الجراح - مشرفة وتمريض وعمال العمليات",
    "content_html": "<div class='policy-doc'><h3>1. ضوابط العمل والتخدير والمجال المعقم:</h3><ul><li>ارتداء زي وحذاء العمليات، الغسل الجراحي للأيدي، فتح الآلات قبل الجراحة مباشرة، والحفاظ على <strong>ضغط هواء موجب</strong> داخل غرفة العمليات، ودرجة حرارة <strong>(20 - 24°م)</strong> ورطوبة <strong>(30% - 60%)</strong>.</li><li><strong>التخدير:</strong> تطهير أو تعقيم المنظار الحنجري، وتطهير جهاز التخدير والمونيتور بعد كل مريض، واتباع الأسلوب المعقم في التخدير النصفي والقسطرة المركزية.</li><li><strong>المجال المعقم:</strong> تغطية المريض بفرش معقم غير منفذ للسوائل، اعتبار كل ما يقع أسفل مستوى المريض غير معقم، ومنع وضع أي سوائل مطهرة على ترابيزة الآلات.</li></ul><h3>2. ما بعد الجراحة وتنظيف غرفة العمليات:</h3><ul><li>تُرسل الآلات للتعقيم المركزي بالأتوكلاف، و<strong>يمنع منعاً باتاً استخدام المطهرات الكيميائية أو الفورمالين</strong> لتعقيم الآلات الجراحية.</li><li>يُمنع التجول بزي العمليات أو السابوه أو الماسك خارج جناح العمليات.</li><li>تنظيف وتطهير أرضيات ومعدات العمليات بـ <strong>كلور 5000 جزء في المليون</strong> في أول اليوم وبين كل مريض وآخر وفي نهاية اليوم، وغسيل الأسقف والحوائط أسبوعياً.</li><li>أي حالة مصابة بعدوى يتم إجراؤها في <strong>نهاية قائمة العمليات (آخر اللستة)</strong> إلا إذا كانت إنقاذ حياة (Life Saving).</li></ul><h3>3. مناطق جناح العمليات:</h3><p>1. منطقة غير محظورة (المدخل، تغيير الملابس) ⬅ 2. منطقة شبه محظورة (الإفاقة، التخدير، مخزن المعقم - يلزمها بدلة وسابوه وغطاء رأس) ⬅ 3. منطقة محظورة (غرف العمليات وتحضير الآلات).</p></div>",
    "plain_text": "السياسة الخاصة بالعمليات الجراحية تهوية موجبة الضغط التخدير داخل غرفة العمليات الحفاظ على المجال المعقم منع الفورمالين لتعقيم الآلات تنظيف غرفة العمليات كلور 5000 جزء في المليون المناطق الثلاث بالعمليات درجة الحرارة 20-24 والرطوبة 30-60%.",
    "slides": [
      {
        "slide_number": 1,
        "slide_title": "قواعد الأمان البيئي والمجال المعقم بالعمليات (IC24)",
        "bullet_points": [
          "بيئة العمليات: ضغط هواء موجب، حرارة (20 - 24°م)، ورطوبة (30% - 60%).",
          "يُمنع وضع أي سوائل على ترابيزة الآلات، وكل ما تحت مستوى السرير يعتبر غير معقم.",
          "حظر استخدام الفورمالين أو الكيماويات لتعقيم الآلات الجراحية (الأوتوكلاف فقط)."
        ]
      },
      {
        "slide_number": 2,
        "slide_title": "التطهير وترتيب الحالات المعدية بالعمليات",
        "bullet_points": [
          "تُطهر أرضيات غرفة العمليات بكلور 5000 ppm في بداية ونهاية اليوم وبين كل حالة.",
          "تُجرى العمليات للحالات المعدية في نهاية اللستة (إلا في حالات إنقاذ الحياة).",
          "يُحظر الخروج بزي العمليات أو السابوه أو الماسك إلى الأقسام والأدوار."
        ]
      }
    ]
