    "date": "1/2/2022",
    "dept": "وحدة المناظير - التعقيم المركزي",
    "purpose": "تنظيف وتطهير المناظير المرنة ما قبل التنظيف منظف إنزيمي اختبار التسرب الغمر في السايدكس 20-90 دقيقة أو OPA لمدة 12 دقيقة أشرطة الاختبار الشطف بماء معقم أو كحول ...",
    "responsibilities": "الطبيب المعالج - طبيب إداري ومشرفة والعاملون بوحدة المناظير والتعقيم",
    "content_html": "<div class='policy-doc'><h3>المراحل السبعة القياسية لمعالجة المناظير المرنة:</h3><ol><li><strong>ما قبل التنظيف (Pre-cleaning):</strong> فور انتهاء الإجراء داخل الغرفة وقبل فصل المنظار، يُمسح خارجياً بفوطة مبللة بمنظف إنزيمي ويُشفط المنظف عبر القنوات حتى يخرج نظيفاً، ثم يُنقل في حاوية مغلقة.</li><li><strong>اختبار التسرب (Leak Test):</strong> توصيل جهاز كشف التسرب وضخ هواء قبل غمر المنظار في الماء وملاحظة أي فقاقيع هواء تدل على ثقب أو تلف.</li><li><strong>التنظيف اليدوي الدقيق:</strong> فك الصمامات والأغطية، وغمر المنظار في المحلول الإنزيمي، وتنظيف جميع القنوات بفرشاة مناسبة المقاس بطريقة الدفع المترددة وتحت سطح الماء.</li><li><strong>الشطف والتجفيف الأولي:</strong> شطف القنوات بالماء وضخ هواء لتجفيفها وفحص المنظار بعدسة مكبرة.</li><li><strong>التطهير عالي المستوى (يدوي أو آلي):</strong> غمر المنظار كلياً وضخ المطهر داخل القنوات في <strong>السايدكس لمدة (20 - 90 دقيقة)</strong> أو في <strong>الأورثوفثالدهيد (OPA) لمدة 12 دقيقة</strong>، مع فحص فعالية المطهر بأشرطة الاختبار يومياً.</li><li><strong>الشطف والتجفيف النهائي:</strong> الشطف بماء معقم (أو ماء مغلي يتبعه شطف القنوات بكحول 70%) ثم التجفيف بهواء مضغوط.</li><li><strong>التخزين الآمن:</strong> يُعلق المنظار في <strong>وضع رأسي</strong> داخل كابينة جيدة التهوية بعد فك الصمامات، ويُعاد تطهيره قبل الاستخدام عند التخزين.</li></ol><h3>ملحقات المنظار:</h3><p>ملاقيط أخذ العينات (Biopsy Forceps) والأدوات المخترقة للأغشية المخاطية يلزم تنظيفها ثم <strong>تعقيمها في الأوتوكلاف</strong>، ويُستخدم ماء معقم في وعاء الماء المتصل بالمنظار.</p></div>",
    "plain_text": "تنظيف وتطهير المناظير المرنة ما قبل التنظيف منظف إنزيمي اختبار التسرب الغمر في السايدكس 20-90 دقيقة أو OPA لمدة 12 دقيقة أشرطة الاختبار الشطف بماء معقم أو كحول 70% التخزين في وضع رأسي تعقيم ملاقيط العينات في الأوتوكلاف.",
    "slides": [
      {
        "slide_number": 1,
        "slide_title": "مراحل معالجة المناظير المرنة (IC27)",
        "bullet_points": [
          "1. مسح وشفط فوري بمنظف إنزيمي داخل غرفة الإجراء قبل جفاف الإفرازات.",
          "2. إجراء اختبار التسرب (Leak Test) تحت الماء قبل البدء في التنظيف.",
          "3. تنظيف القنوات بالفرش والمحلول الإنزيمي ثم الشطف والتجفيف بالهواء."
        ]
      },
      {
        "slide_number": 2,
        "slide_title": "التطهير عالي المستوى والتخزين للمناظير",
        "bullet_points": [
          "الغمر الكامل في السايدكس (20-90 دقيقة) أو OPA (12 دقيقة) مع فحص الشريط الكاشف.",
          "الشطف بالماء المعقم والتجفيف بالكحول 70% والهواء المضغوط.",
          "التخزين في وضع رأسي بكابينة مهواة، وتعقيم ملاقيط العينات في الأوتوكلاف."
        ]
      }
    ]
