        "slide_title": "إدارة الإنذارات الحرجة للأجهزة الطبية (CSS.02)",
        "bullet_points": [
          "تشمل: المونيتور، التنفس الصناعي، مضخات وسرنجات المحاليل، الحضانات، وصدمات القلب.",
          "يضبط الطبيب المعالج الحدود العليا والدنيا للإنذار بما يناسب حالة كل مريض.",
          "تُفحص كفاءة الإنذارات الصوتية والضوئية في بداية كل شفت تمريضي وتُوثق."
        ]
