          "الغسيل الخالي من الهيبارين (لحالات النزف): ضخ 50 سم محلول ملح 0.9% كل ساعة.",
          "قفل القسطرة المركزية المستديمة بعد الجلسة بأمبول هيبارين ومحلول ملح حسب أمر الطبيب."
