    "responsibilities": "مدير المستشفى - جميع أطباء وفريق العمل",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تقدم المستشفى خدمات الرعاية المتثامنة والمتماثلة لجميع المرضى بغض النظر عن خلفياتهم أو أماكن إقامتهم أو توقيت حضورهم، لضمان عدم التمييز وتوفير رعاية عالية الجودة للجميع.</p><h3>إجراءات العمل:</h3><ul><li>تلتزم كافة الأقسام بتطبيق أدلة العمل الإكلينيكية المعتمدة لتقديم مستويات رعاية متماثلة للحالات المتشابهة.</li><li>توفير خدمات الطوارئ والإنقاذ والتشخيص والعناية المركزة والغسيل الكلوي على مدار الساعة طوال أيام الأسبوع دون أي تفرقة.</li><li>توفير آلية لتلقي الش شكاوى المتعلقة بأي شبهة تمييز أو تقصير والتحقيق فيها فوراً بواسطة إدارة الجودة.</li></ul></div>",
    "plain_text": "تقديم رعاية موحدة دون تمييز بغض النظر عن خلفية المريض أو موقعه أو وقت تقديم الخدمة وتوفير خدمات الطوارئ والعناية والتشخيص دون تمييز.",
