    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تحديد الإجراءات والمسؤوليات لتنفيذ التقييم الطبي الأولي وإعادة التقييم الدوري للمرضى المدخولين بدقة لضمان التشخيص السليم.</p><h3>إجراءات التقييم الطبي:</h3><ul><li>إجراء فحص إكلينيكي شامل وكتابة التاريخ المرضي المفصل خلال <strong>24 ساعة كحد أقصى</strong> من دخول المريض للقسم الداخلي.</li><li>إجراء التقييمات التخصصية المطلوبة مثل تقييم مخاطر الجلطات (VTE) وقرح الفراش ومستوى الألم عند الدخول.</li><li>إعادة التقييم اليومي (خلال كل شفت والمرور الطبي) وتوثيق التطور الإكلينيكي (Progress Notes) وتحديث خطة العلاج بانتظام.</li></ul></div>",
    "plain_text": "التقييم وإعادة التقييم الطبي الفحص الشامل خلال 24 ساعة من الدخول التاريخ المرضي المفصل تقييم VTE وقرح الفراش خطة الرعاية الطبية.",
