    "responsibilities": "الأطباء - هيئة التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان حق المريض في تقييم وتخفيف الألم بفعالية وأمان طوال فترة تلقيه الرعاية بالمستشفى.</p><h3>أدوات قياس وتقييم الألم:</h3><ul><li><strong>المقياس الرقمي (NRS 0-10):</strong> للبالغين الواعين (من 0 بدون ألم إلى 10 أسوأ ألم متوقع).</li><li><strong>مقياس الوجوه (Wong-Baker):</strong> للأطفال الأكبر سنًّا وذوي الإعاقة اللغوية.</li><li><strong>مقياس FLACC:</strong> للأطفال الصغار وغير القادرين على التعبير.</li><li><strong>مواعيد التقييم:</strong> عند الدخول، في كل شفت، قبل وبعد إعطاء المسكنات، وقبل وبعد الإجراءات التداخلية.</li></ul></div>",
    "plain_text": "تقييم والتعامل مع الألم مقياس الرقم الرقمي Numerical Pain Rating مقياس وجوه بيكر للأطفال مقياس FLACC العناية ومتابعة المسكنات.",
