    "purpose": "تقييم مخاطر السقوط مقياس زنكبوه Johns Hopkins للبالغين مقياس هامبتي دامبتي Humpty Dumpty للأطفال احتياطات منع السقوط رفع جوانب السرير....",
    "responsibilities": "الأطباء - التمريض - الأمن - الفنيين - إدارة البيئة",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>حماية المرضى من الإصابات الناتجة عن السقوط من خلال التقييم المبكر للمخاطر وتطبيق حزمة الاحتياطات الوقائية.</p><h3>أدوات التقييم واعتماد الخطورة:</h3><ul><li><strong>للبالغين:</strong> استخدام مقياس زنكبوه (Johns Hopkins Fall Risk Assessment)؛ الدرجة من 6 إلى 13 (خطورة متوسطة)، و14 فأكثر (خطورة عالية).</li><li><strong>للأطفال:</strong> استخدام مقياس هامبتي دامبتي (Humpty Dumpty Scale).</li><li><strong>إجراءات الوقاية للحالات عالية الخطورة:</strong> وضع سوار مميز (أصفر)، وضع علامة تحذيرية على السرير، رفع جوانب السرير بانتظام، وضع زر النداء في متناول اليد، وتثقيف المريض وذويه.</li></ul></div>",
    "plain_text": "تقييم مخاطر السقوط مقياس زنكبوه Johns Hopkins للبالغين مقياس هامبتي دامبتي Humpty Dumpty للأطفال احتياطات منع السقوط رفع جوانب السرير.",
