    "responsibilities": "الأطباء - هيئة التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>منع حدوث قرح الفراش للمرضى غير القادرين على الحركة من خلال التقييم الدوري وتطبيق خطط الوقاية التمريضية.</p><h3>أدوات التقييم والوقاية:</h3><ul><li><strong>مقياس برادين (Braden Scale):</strong> لتقييم خطورة قرح الفراش للبالغين (الدرجة ≤ 16 تعني وجود خطورة متوسطة إلى عالية).</li><li><strong>الإجراءات الوقائية:</strong> برنامج تقليب منتظم للمريض <strong>كل ساعتين</strong> بجدول زمني موثق، استخدام المرتبة الهوائية للحالات عالية الخطورة، الحفاظ على جفاف ونظافة الجلد، واستخدام المرطبات.</li><li><strong>في حال حدوث قرحة:</strong> توثيق درجتها ومساحتها، استشارة الطبيب، وتحديث خطة الرعاية التمريضية والجراحية.</li></ul></div>",
    "plain_text": "مخاطر قرح الفراش مقياس برادين Braden scale مقياس نورتون Norton scale جدول التقليب كل ساعتين المرتبة الهوائية العناية بالجلد.",
