    "responsibilities": "الأطباء المعالجون - الصيادلة الإكلينيكيون - التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تقييم جميع المرضى المدخولين لمعرفة مدى خطورة تعرضهم للجلطات الدموية الوريدية العميقة (DVT) والانسداد الرئوي (PE) وتوفير الوقاية المناسبة.</p><h3>إجراءات التقييم والوقاية:</h3><ul><li><strong>للحالات الطبية:</strong> استخدام مقياس جنيف (Geneva Risk Score) خلال 24 ساعة من الدخول.</li><li><strong>للحالات الجراحية:</strong> استخدام مقياس كابريني (Caprini Score) لتحديد درجات الخطورة.</li><li><strong>وسائل الوقاية:</strong> إعطاء مضادات التجلط الوقائية (مثل LMWH) بحسب أمر الطبيب وموانع النزف، أو استخدام الوقاية الميكانيكية (مثل الجوارب الضاغط أو أجهزة الضغط المتقطع SCD) وتشجيع الحركة المبكرة.</li></ul></div>",
    "plain_text": "الجلطات الدموية الوريدية VTE مقياس جنيف Geneva للحالات الطبية مقياس كابريني Caprini للحالات الجراحية الوقاية الدوائية والميكانيكية الجورب الضاغط.",
