    "responsibilities": "الأطباء - هيئة التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>وضع ضوابط صارمة للتعامل مع الأوامر الشفهية والتليفونية وقصرها على حالات الطوارئ القصوى فقط لضمان سلامة المرضى.</p><h3>إجراءات العمل:</h3><ul><li>تُمنع الأوامر الشفهية والتليفونية إلا في حالات الطوارئ أو العمليات الحرجة التي يتعذر فيها الكتابة الفورية.</li><li>يقوم المتلقي (التمريض) بإعادة قراءة الأمر الشفهي صراحة على الطبيب (Read-Back) وتأكيده قبل التنفيذ.</li><li>يلتزم الطبيب بتوقيع وكتابة الأمر رسمياً في الملف الطبي خلال <strong>24 ساعة</strong> كحد أقصى.</li></ul></div>",
    "plain_text": "الأوامر الشفهية والتليفونية قصرها على حالات الطوارئ إعادة قراءة الأمر وتأكيده Read-Back توقيع الطبيب خلال 24 ساعة.",
