    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تنظيم خطوات طلب الدم ومشتقاته وإجراءات النقل الآمن لمنع حدوث التفاعلات التداخلية والأخطاء المميتة.</p><h3>إجراءات العمل:</h3><ul><li>يُحرر نموذج طلب الدم بدقة مع توقيع الطبيب المعالج وتحديد مكون الدم المطلوب وكميته ودرجة الاستعجال.</li><li>سحب عينة التوافق باسم المريض الثلاثي ورقم الملف والتأكد من مطابقة السوار التعريفي.</li><li>إجراء التحقق المزدوج (Double Check) بواسطة ممرضتين عند استلام وحدة الدم بجانب سرير المريض للتأكد من مطابقة بيانات الوحدة لبيانات المريض تماماً قبل البدء في النقل.</li></ul></div>",
    "plain_text": "طلب ونقل الدم ومشتقاته نموذج طلب الدم فصيلة الدم والتوافق التحقق المزدوج قبل النقل مراقبة المريض.",
