    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>توحيد قائمة الاختصارات والرموز الطبية المسموحة ومنع استخدام الاختصارات الخطرة التي قد تسبب أخطاء في وصف وتفسير الأدوية والإجراءات.</p><h3>إجراءات العمل:</h3><ul><li>الالتزام بقائمة الاختصارات المعتمدة والموصى بها رسمياً داخل المستشفى.</li><li>المنع التام لاستخدام الاختصارات الخطرة والمحظورة دولياً (مثل اختصار U للوحدات أو µg بطريقة ملتبسة) لتجنب أخطاء الجرعات.</li><li>كتابة الجرعات والأدوية بالأسماء الكاملة عند وجود أي شك لتفادي سوء الفهم.</li></ul></div>",
    "plain_text": "الاختصارات والرموز الموحدة قائمة الاختصارات الممنوعة منع اللبس في كتابة الأدوية.",
