    "responsibilities": "مسئولو الملفات الطبية - الأمن - التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تنظيم عمليات تداول وحفظ وسحب الملفات الطبية لضمان سريتها وحمايتها من التلف أو الضياع وإتاحتها للمختصين عند الحاجة.</p><h3>إجراءات العمل:</h3><ul><li>الحفاظ التام على سرية بيانات المريض وملفه الطبي ومنع الاطلاع عليه إلا لفريق الرعاية المختص.</li><li>تنظيم حركة تداول الملفات بين الأقسام وعودتها لقسم الملفات الطبية بانتظام مع تسجيل بيانات السحب.</li><li>حفظ الملفات الطبية في أماكن مؤمنة ضد الحريق والتلف والوصول غير المصرح به.</li></ul></div>",
    "plain_text": "تداول الملف الطبي سرية المعلومات الطبية حماية الملفات من التلف أو الضياع تنظيم سحب وإرجاع الملفات.",
