    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان إنشاء ملف طبي دقيق ومكتمل لكل مريض يدخل المستشفى ومراجعته دورياً للتأكد من استيفاء كافة المستندات والبيانات الإكلينيكية.</p><h3>إجراءات العمل:</h3><ul><li>إنشاء ملف طبي ورقي أو إلكتروني لكل مريض عند دخوله يحمل تعريفه الصحيح (الاسم، الرقم الطبي).</li><li>التزام الأطباء والتمريض بتوثيق كافة الفحوصات والتقييمات وأوامر العلاج بالتاريخ والوقائع والتوقيع الثلاثي بانتظام.</li><li>مراجعة الملف الطبي بعد خروج المريض للتأكد من استيفائه واكتماله قبل الحفظ النهائي.</li></ul></div>",
    "plain_text": "إنشاء ومراجعة الملف الطبي استكمال النماذج والبيانات التوقيع والتاريخ والتوثيق السليم.",
