    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تنظيم ضوابط خروج المرضى نهائياً أو خروجهم المؤقت أو إحالتهم لمستشفيات أخرى بطريقة آمنة وموثقة.</p><h3>إجراءات العمل:</h3><ul><li>إصدار قرار الخروج النهائي أو الإحالة بمعرفة الطبيب المعالج مع استكمال كافة الفحوصات والتقارير الطبية.</li><li>تحرير ملخص خروج شامل (Discharge Summary) يسلم للمريض يوضح الأدوية، مواعيد المتابعة، والتعليمات الغذائية.</li><li>تنظيم الخروج المؤقت (بناءً على طلب المريض أو مسؤوليته) بإقرار توقيعي موثق بعد شرح المخاطر الطبية.</li></ul></div>",
