    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان تخزين الأدوية والمستلزمات الطبية في ظروف بيئية ومعيارية سليمة تحافظ على فعاليتها وصلاحيتها للاستخدام.</p><h3>إجراءات العمل:</h3><ul><li>التحكم في درجات حرارة الغرف وثلاجات الأدوية وتسجيلها دورياً (الثلاجة بين 2 إلى 8 درجات مئوية).</li><li>ترتيب الأدوية بطريقة منظمة، وفحص صلاحيات الأدوية بانتظام، والتخلص الفوري من الأدوية منتهية الصلاحية.</li></ul></div>",
    "plain_text": "تخزين الأدوية بطريقة صحيحة وآمنة درجات الحرارة والتهوية والتحكم في صلاحية الأدوية بالثلاجات والصيدليات.",
