    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>منع الأخطاء الجسيمة الناتجة عن تداول وإعطاء الأدوية عالية الخطورة وعالية التركيز التي تسبب أضراراً بالغة للمريض عند الخطأ في جرعاتها.</p><h3>إجراءات العمل:</h3><ul><li>تحديد قائمة الأدوية عالية الخطورة (مثل الإلكتروليتات المركزة، مخدرات، أدوية السيولة).</li><li>تمييز أرفف وعبوات هذه الأدوية بملصقات تحذيرية واضحة (عالية الخطورة).</li><li>إجراء المراجعة المزدوجة (Double Check) بين ممرضتين قبل تحضير وإعطاء هذه الأدوية للمريض.</li></ul></div>",
